"""Clarification tasks, not an exhaustively proven unanswerable set."""
items=[]
def b(question, parents, missing, answer, prohibited, difficulty="Medium", reason="题干缺少会影响政策适用的条件；需先给条件化说明或提出有效澄清，不能直接选定一项待遇。", extra=None):
    items.append(dict(question_id=f"mb2-b{len(items)+1:03d}",question=question,parent_question_ids=[f"mb2-{n:03d}" for n in parents],missing_conditions=missing,reference_answer=answer,prohibited_inferences=prohibited,difficulty=difficulty,difficulty_reason=reason,extra_evidence_specs=extra or []))

b("我医保交了很多年，现在退休了，以后是不是不用交了？",[71], ["参保城市与适用年度","职工或居民医保及参保形式","性别、累计年限及本地实际缴费年限"],"应先确认参保地、险种、年限等。可举题库内徐州2019职工办法作有条件的历史例子，但不能直接替用户认定已满足退休医保条件。",["把养老保险退休资格等同退休医保资格","把徐州历史男25女20年当全国唯一条件"])
b("医院说我这笔费用先自付20%，是不是最后只要自己出20%？",[74], ["项目是否目录内及先付规则","其余费用适用起付线、报销比例和限额"],"可先说明先行自付不是最终负担，剩余费用还需按待遇规则结算。要计算具体金额，应补充合规费用、报销比例及起付限额等条件。",["直接保证最终负担20%"])
b("我今年高血压药花了3000元，医保能报多少钱？",[98,168], ["参保地、医保类型和年度","是否两病待遇认定、单病或双病","合规用药金额、就医机构及已用年度额度"],"先询问适用地区年度、两病待遇和费用条件，不能直接套某一历史版本。可说明徐州2019与2022规则存在变化，需要匹配版本后计算。",["无条件使用200元旧起付线","忽略年度已支付金额"],"Hard","版本变化和剩余额度共同决定结果，题干缺失的不是一个简单关键词。")
b("我有残疾证，居民医保能免费参保吧？",[176], ["参保地和年度","残疾等级、劳动能力及其他资助身份"],"先核实当地年度与资助身份。库内徐州2024解读对相关残疾资助设有等级、劳动能力等条件，不能仅凭有证即判断免费。",["把任意残疾证都当作全额资助证明"])
b('我给家人买商业医疗险，能刷我医保个人账户吗？', [47, 180], ['城市、年度及具体商业保险产品', '家属关系、参保情况及个人账户适用条件'], '应确认地区年度、具体保险产品、亲属关系和参保条件。可有条件说明江苏2021补充医保十问允许职工个人账户历年结余4000元以上部分，为本人或参加本统筹区基本医保的配偶、父母、子女购买商业补充医保；不能用居民医保缴费共济直接推出任意商业险可购买。', ['把居民医保缴费共济等同任意商业险支付'])
b("我医保断缴了两个月，现在补上，之前看病的钱能补报吗？",[70,77], ["险种及是否长护险","参保地、年度、单位或个人参保","欠费时间、补缴到账时间和费用发生时间"],"先区分职工医保与长护险等险种、参保形式和时间线。库内规则对单位欠费与长护险欠费处理不同，不能一律答可追补或不可追补。",["用长护险不追溯规则覆盖全部医保","忽略月底补缴等时间分支"],"Hard","相似断缴表述指向不同保险制度，且时间边界可能改变历史费用承担方。")
b("我爷爷生活不能自理，能马上领长护险待遇吗？",[79,163], ["所在试点及当地年度规则","参保状态、规范治疗和失能持续时间","是否提出申请及评估结论"],"应询问当地试点、参保与评估条件。可说明失能事实通常不直接等于待遇资格，需按适用规则申请评估，不应仅凭生活不能自理就承诺立即领取。",["省略正式评估直接认定等级与待遇"])
b("评估机构给了我41分，是不是重度，能让家人护理同时住机构报销吗？",[80,86], ["城市及评估年度、评分体系","适用照护方式和拟申请待遇"],"先确认是哪套评分和待遇规则。若限定徐州市区2021年1月细则，41分为中度且方式待遇不能叠加；在确认前不把这一历史标准推广到其他地区年度。",["把所有41分都判为同一等级","默认不同照护方式可叠加"],"Hard","需先确定评分体系，再串联等级、可选方式与待遇互斥三个判断。")
b("我对长护险评估不满意，现在还能申请复核吗？",[83], ["地区、适用版本","收到评估结论书的日期及当前申请日期"],"先问参保地和收到结论日期，再计算当地复核期限。可有条件说明徐州2021年1月细则的15日期限，不能直接保证用户尚在期限内。",["从评估申请日计算异议期限"])
b("我今年住院花了十万元，大病保险应该给我报多少？",[103,104,105], ["险种、地区及年度","基本医保后个人合规负担金额","当地起付线、分段比例、困难身份及年度累计"],"先明确大病保险计算用基本医保后合规个人负担，而非账单总额；具体金额需当地起付分段和身份、年度累计等信息。",["将十万元全部直接乘60%","把指导意见的比例下限当人人固定比例"],"Hard","要重构费用计算基数，再匹配分段和困难身份，不能从账单总额一步求解。")
b("这个进口抗癌药，医保一定能报吗？",[109,110], ["药品通用名和目录版本","患者适应症、参保地险种及特药认定"],"先问具体药名、适应症与参保条件，再查适用目录。不能仅由进口或抗癌属性承诺可报；进入特药管理还可能有程序条件。",["把所有进口抗癌药认定为特药"])
b("我在外地看了门诊，是按当地医保直接结算还是回家报销？",[212,234], ["参保地、就医地、发生年月","普通门诊或专项病种待遇、备案和联网情况"],"先确认门诊类型、年月与两地信息；库内跨省住院通知不能直接代替普通门诊规则，新冠专项零报规定也不能推广到全部门诊。",["把住院直接结算规则用于所有门诊","把疫情阶段专项比例用于普通疾病"])
b('新冠住院出院后，自费那部分政府都给补吧？', [207, 213, 215], ['地区及入院日期', '适用政策阶段、个人救助身份与费用范围'], '先核对入院日期和当地政策阶段，并区分所有自费与符合治疗方案的住院费用经基本医保、大病保险、医疗救助等支付后的个人负担。徐州库内2023年3月底前与4月起规则不同，4月医疗救助不是对所有人自动发放；旧阶段也不能概括为任意自费全补。', ['只看出院日期判断旧专项政策', '无限延长早期财政补助'], 'Hard', '时间分界按入院而非出院，后阶段还涉及救助资格，错误版本可完全改变结论。')
b("我退休后个人账户一年只有480元，是不是肯定少划了？",[67], ["参保地、适用年度、年龄和参保形式","金额是全年合计还是部分月份"],"需核对当地年度、年龄、是否有个人账户及全年金额后判断。库内徐州2019有退休人员年度保底分支，但不能用它直接判定用户当前账户有误。",["把部分月份金额当全年","未核对年龄就套800元保底"])
b("我转到另一座城市工作，原医保账户余额能直接提现吗？",[68,69], ["是医保关系转移还是退出参保","退出时间及是否再次参职工医保","适用城市规则与申请事由"],"先区分转移与退出提取。库内徐州2019规定关系转移时余额随转，退出满规定期间且未再参保另有申请条件，不能把换工作等同提现资格。",["将跨城就业等同退保满一年"])
b("我符合救助条件，既然没有起付线，是不是所有看病费用都不用自己出？",[193], ["具体医疗救助身份及地区年度","合规费用与基本医保、大病保险支付情况"],"可明确无起付线不等于所有费用全额支付；还需按基本医保、大病保险后的个人合规负担和当地救助标准计算。应补充身份和费用信息。",["无起付线等同零自付"])
b("单位说医保缓缴了，所以我生孩子不能报销，是真的吗？",[140,141], ["适用地区年度及缓缴政策","单位是否依法纳入缓缴、个人部分缴纳情况"],"先区分依法政策性缓缴与普通欠缴。江苏2022阶段性政策中依法缓缴不影响职工正常医保及生育待遇，但不能未经核实就断言单位适用该政策。",["把任何企业欠费都认定为依法缓缴"])
b("我现在还可以申请2020年那次医保费减半吗？",[223,225], ["所申请费款的所属期","当前办理事项与是否历史退抵、适用地方政策"],"不能将2020阶段性减征当作无限期现行优惠；应确认是历史所属期退抵还是当前月份缴费，并核查对应办理规则。",["按当前付款日直接套2020减征"])
b("我想举报医保骗保，查实后奖励一定有五万元吗？",[245,246], ["适用地区及奖励规则版本","举报资格、追回基金金额和裁量条件"],"不能把最高额当固定奖金。可说明库内该徐州历史办法有比例、封顶及无可量化数额等分支，须确定版本、资格和追回金额后判断。",["查实即无条件固定奖5万元"])
b('我已经被认定严重失信，半年后就能把所有信用记录删掉吗？', [273, 275], ['适用细则、平台及公示起算日', '处罚履行、修复条件和审核状态'], '先确认适用细则、平台、公示起算和处罚履行等条件。库内细则分别规定严重失信3年公示和行政处罚信息最短公示6个月，不能混同；达到最短公示时间也不等于自动删除，修复还有适用条件、申请及审核。', ['把申请修复门槛当自动完成修复', '把各平台流程认定完全相同'], extra=[{'source_id': '79234', 'lines': [63, 63]}])
b("医院想买一批没挂网的产品，可以先买后补手续吗？",[257,266,281,284], ["药品还是医用耗材、具体类别","适用年度和制度版本","临床急需条件、平台状态、年度应急额度"],"先问产品类别、年月、急需与挂网情况。库内旧备案要求先备案，后续药品和耗材有各自应急采购机制及不同额度，不能给统一的先买许可。",["把药品3%与耗材5%互换","拼接旧备案与新应急规则"],"Hard","跨产品、跨版本的机制和额度不同，必须先路由到正确规则再评估例外。")
b("供应商说已经挂网了，医院就必须按那个价买，不能再谈价吗？",[265,280,286], ["药品或耗材及政策年度","是否国家谈判、储备或集采中选等类别"],"须区分一般挂网产品与不再议价的特殊类别，并匹配年度。一般挂网价格可能作为议价上限，不能据已挂网概括所有产品都不得议价。",["所有挂网产品一律不得议价"])
b("牙冠写的是120元，装一颗牙是不是总共只花120元？",[295], ["120元是牙冠产品价还是完整诊疗报价","是否还有种植体与医疗服务等项目"],"先确认报价对象和费用构成。牙冠产品挂网价包含列明加工配送等，不等于全部种植诊疗总价；需查具体服务清单，不能报出未知总费用。",["把单颗牙冠价当全部口腔种植费用"])
b('我们是民营医院，医保定点肯定比公立医院多一套准入条件吧？', [151], ['适用地区年度与具体机构类型、定点事项'], '应确认地区年度和具体定点事项。库内2016城乡居民医保整合意见要求非公立医疗机构与公立享受同等定点管理政策，因此不能仅因民营身份推断必有额外一套准入条件；具体资质仍需按适用规则审查。', ['混同定点准入与阳光采购参与规则'])
b("我们照护机构已经开业三个月，有20张床，是不是马上能签长护险协议？",[89,90,95], ["养老或医疗机构类型","人员、资质、服务和申请评估等其他条件","当地规则和适用年度"],"应确认机构类别及完整准入条件；运营时间与床位只是部分门槛，不能替代人员比例、评估、公示与培训等签约要求。",["把满足两个最低门槛当已完成签约资格"],"Hard","不同机构类别条件不同，形式门槛与后续签约关卡需要合并判断。")
b("我查到一个医院创新项目能自主定价，是不是想收多少都行，也不用备案？",[299], ["是否属于该制度已公布项目及试行期","原申报单位还是其他实施机构"],"不能据自主定价推导无限定价。应确认项目试行状态和实施机构角色，按库内规则还需成本等依据、备案公示，其他机构同项目不得高于申报单位价格。",["把自主定价等同免备案和无上限"])
b('这个创新项目试行满两年了，是不是自然转成正式项目？', [299, 300], ['实际批准试行期限', '是否提出转归及获批、是否获准继续试行'], '不自动转正式；应核查实际期限和转归、延续许可。库内文件的试行期是不少于2年，不能仅凭满两年认定已到期或已转归。', ['把不少于两年理解为固定两年', '默认期满自动永久批准'])
b("网上一篇2019年的医保政策说这样报销，2027年也照这个算吗？",[127,215,284], ["具体地区、险种、文件和拟发生费用日期","后续修订废止及届时适用文件"],"应说明历史文档不能单独证明2027仍有效，需要核查后续有效文件；可解释旧文历史含义，但不能据当前快照保证未来报销标准。",["声称全库没有相关政策","把未知未来标准编成确定金额"],"Medium","这是现行有效性与未来可证实性边界，不把缺证据自动视作高难多跳题。")
b("这些文件的日期不一样，医保待遇究竟按文件发布日还是生效日算？",[215,300], ["具体文件条款和待遇事项","费用发生、入院等题中相关时间"],"先让用户指定文件和事项；应按正文生效与过渡条款，有些待遇还按入院日划分，不能统一只按网页发布时间或文件签发日。",["一概用元数据发布日期覆盖正文生效条款"])
b("医院给我的收费清单只有一个套餐总价，我怎么判断有没有多收费？",[249,250,253], ["项目明细、计价单位、单价、数量与医疗场景","对应价格规则及是否允许组合收费"],"可建议取得项目明细与适用价格依据，核查是否自立项目或拆分、组套多收；仅一个总价不足以确认违规或具体多收金额。",["未经核对即判医院违法","编造应退金额"])
